# AUTOMATICALLY GENERATED BY CLOUDMOVE MIGRATION ENGINE
# MAIN INFRASTRUCTURE MODULE
# ============================================================

# Dynamic secure credentials generation (zero hardcoded secrets)
resource "random_password" "db_master_password" {
  length  = 24
  special = false
}

locals {
  effective_db_password = var.db_password != null && var.db_password != "" ? var.db_password : random_password.db_master_password.result
}

# Network & Isolation Boundaries
resource "aws_vpc" "target_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name        = "cloudmove-target-vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.target_vpc.id
  tags = {
    Name = "cloudmove-igw"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.target_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  tags = {
    Name = "cloudmove-public-subnet"
  }
}

resource "aws_subnet" "private_subnet_a" {
  vpc_id            = aws_vpc.target_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.aws_region}a"
  tags = {
    Name = "cloudmove-private-subnet-a"
  }
}

resource "aws_subnet" "private_subnet_b" {
  vpc_id            = aws_vpc.target_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "${var.aws_region}b"
  tags = {
    Name = "cloudmove-private-subnet-b"
  }
}

resource "aws_security_group" "app_sg" {
  name        = "cloudmove-app-sg"
  description = "Security group for migrated application workloads"
  vpc_id      = aws_vpc.target_vpc.id
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 3000
    to_port     = 3000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 8000
    to_port     = 8000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "cloudmove-app-sg"
  }
}

resource "aws_security_group" "data_sg" {
  name        = "cloudmove-data-sg"
  description = "Security group for migrated data services"
  vpc_id      = aws_vpc.target_vpc.id
  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.app_sg.id]
  }
  ingress {
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [aws_security_group.app_sg.id]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "cloudmove-data-sg"
  }
}

resource "aws_db_subnet_group" "db_subnets" {
  name       = "cloudmove-db-subnets"
  subnet_ids = [aws_subnet.private_subnet_a.id, aws_subnet.private_subnet_b.id]
  tags = {
    Name = "cloudmove-db-subnets"
  }
}

# Migrated Resource: CocoaApp-runtime-host (compute-cocoaapp-host)
resource "aws_instance" "compute_cocoaapp_host" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.public_subnet.id
  tags = {
    Name        = "cocoaapp-runtime-host"
    CMIR_Type   = "container"
    CMIR_ID     = "compute-cocoaapp-host"
    ManagedBy   = "CloudMove"
  }
}

# Migrated Resource: CocoaApp (app-cocoaapp)
resource "aws_instance" "app_cocoaapp" {
  ami                         = var.ami_id != "" ? var.ami_id : "ami-0c55b159cbfafe1f0"
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public_subnet.id
  vpc_security_group_ids     = [aws_security_group.app_sg.id]
  associate_public_ip_address = true
  tags = {
    Name        = "cocoaapp"
    CMIR_ID     = "app-cocoaapp"
    ManagedBy   = "CloudMove"
  }
}

# Migrated Resource: CocoaApp-backend-host (compute-cocoaapp-backend)
resource "aws_instance" "compute_cocoaapp_backend" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.public_subnet.id
  tags = {
    Name        = "cocoaapp-backend-host"
    CMIR_Type   = "container"
    CMIR_ID     = "compute-cocoaapp-backend"
    ManagedBy   = "CloudMove"
  }
}

# Migrated Resource: CocoaApp-backend (app-cocoaapp-backend)
resource "aws_instance" "app_cocoaapp_backend" {
  ami                         = var.ami_id != "" ? var.ami_id : "ami-0c55b159cbfafe1f0"
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public_subnet.id
  vpc_security_group_ids     = [aws_security_group.app_sg.id]
  associate_public_ip_address = true
  tags = {
    Name        = "cocoaapp-backend"
    CMIR_ID     = "app-cocoaapp-backend"
    ManagedBy   = "CloudMove"
  }
}

# Migrated Resource: CocoaApp-frontend-host (compute-cocoaapp-frontend)
resource "aws_instance" "compute_cocoaapp_frontend" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.public_subnet.id
  tags = {
    Name        = "cocoaapp-frontend-host"
    CMIR_Type   = "container"
    CMIR_ID     = "compute-cocoaapp-frontend"
    ManagedBy   = "CloudMove"
  }
}

# Migrated Resource: CocoaApp-frontend (app-cocoaapp-frontend)
resource "aws_instance" "app_cocoaapp_frontend" {
  ami                         = var.ami_id != "" ? var.ami_id : "ami-0c55b159cbfafe1f0"
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public_subnet.id
  vpc_security_group_ids     = [aws_security_group.app_sg.id]
  associate_public_ip_address = true
  tags = {
    Name        = "cocoaapp-frontend"
    CMIR_ID     = "app-cocoaapp-frontend"
    ManagedBy   = "CloudMove"
  }
}

# Migrated Resource: tcp-80 (port-cocoaapp-80)
# Migrated Resource: tcp-3000 (port-cocoaapp-3000)
# Migrated Resource: tcp-8000 (port-cocoaapp-8000)
# Migrated Resource: cocoaapp-workload-identity (identity-cocoaapp-sa)
resource "aws_instance" "identity_cocoaapp_sa" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.public_subnet.id
  tags = {
    Name        = "cocoaapp-workload-identity"
    CMIR_Type   = "identity"
    CMIR_ID     = "identity-cocoaapp-sa"
    ManagedBy   = "CloudMove"
  }
}

# Migrated Resource: cocoaapp-supabase-baas (dep-cocoaapp-supabase-baas)
resource "aws_db_instance" "dep_cocoaapp_supabase_baas" {
  identifier             = "cocoaapp-supabase-baas"
  engine                 = "postgres"
  instance_class         = "db.t3.micro"
  allocated_storage      = 20
  username               = "cloudmove_admin"
  password               = local.effective_db_password
  publicly_accessible    = false
  skip_final_snapshot    = true
  db_subnet_group_name   = aws_db_subnet_group.db_subnets.name
  vpc_security_group_ids  = [aws_security_group.data_sg.id]
  tags = {
    Name        = "cocoaapp-supabase-baas"
    CMIR_ID     = "dep-cocoaapp-supabase-baas"
